# user → conversation_id 的内存映射（单机演示）
convs: dict[str, str] = {}

def chat(user: str, query: str) -> str:
    payload = {'inputs': {}, 'query': query, 'response_mode': 'blocking', 'user': user}
    if user in convs:
        payload['conversation_id'] = convs[user]
    r = requests.post(url, headers=headers, json=payload, timeout=30).json()
    convs[user] = r['conversation_id']
    return r['answer']
